            Js table = ((MatchMaking.VERDICT_LABELS.Get(MatchMaking.pickLocale(loc)).NonNullish ?? MatchMaking.VERDICT_LABELS.Get("en")).NonNullish ?? Js.Obj());
            return (Locales.own(table, v).NonNullish ?? v);
        }

        internal static Js verdictDescription(Js loc, Js verdict)
        {
            Js l = MatchMaking.pickLocale(loc);
            Js south = MatchMaking.SOUTH_MATCH.Get(l);
            if (south)
            {
                if (((Js.StrictEquals(verdict, Js.S("excellent")) || Js.StrictEquals(verdict, Js.S("good"))) || Js.StrictEquals(verdict, Js.S("fair"))))
                {
                    return south.Get("verdict").Get(verdict);
                }
                return south.Get("verdict").Get("poor");
            }
            switch (verdict.CaseKey())
            {
                case "excellent":
                if (Js.StrictEquals(l, Js.S("hi")))
                {
                    return Js.S("उत्तम मिलान — सभी क्षेत्रों में सामंजस्य की संभावना अधिक है।");
