                    return Js.S("उत्तम जुळवणी — सर्व क्षेत्रांत सामंजस्याची शक्यता अधिक आहे.");
                }
                return Js.S("Excellent match — high compatibility across all areas.");
                case "good":
                if (Js.StrictEquals(l, Js.S("hi")))
                {
                    return Js.S("अच्छा मिलान — विवाह के लिए अनुकूल योग।");
