                return Js.S("cancelled");
            }
            if (d.Get("HasDosha"))
            {
                return Js.S("has-dosha");
            }
            return Js.S("no-dosha");
        }

        internal static Js joinStrings(Js items, Js sep)
        {
            return (Js.IsArray(items) ? items.Join(sep) : Js.S(""));
        }

        internal static Js doshaSummary(Js loc, Js d)
        {
            Js l = MatchMaking.pickLocale(loc);
            Js south = MatchMaking.SOUTH_MATCH.Get(l);
            if (south)
            {
                if ((!d.Get("Computed")))
                {
                    return south.Get("mangalNotComputed");
                }
                if ((!d.Get("HasDosha")))
                {
                    return south.Get("mangalNone");
                }
                Js type = (Js.StrictEquals(d.Get("Type"), Js.S("purn")) ? south.Get("typePurn") : (Js.StrictEquals(d.Get("Type"), Js.S("mild")) ? south.Get("typeMild") : (d.Get("Type").NonNullish ?? Js.S(""))));
                Js hs = Shared.listOf(d.Get("HousesOccupied"));
                Js lag = hs.Filter(Js.Fn(args1_ =>
                {
                    Js h = Js.Arg(args1_, 0);
                    return Js.Greater(h, Js.N(0d));
                })).Map(Js.StringFunction);
                Js moon = hs.Filter(Js.Fn(args1_ =>
                {
                    Js h2 = Js.Arg(args1_, 0);
                    return Js.Less(h2, Js.N(0d));
                })).Map(Js.Fn(args1_ =>
                {
                    Js h3 = Js.Arg(args1_, 0);
                    return Js.ToStringValue(Js.Negate(h3));
                }));
                Js parts = Js.Arr();
                if (lag.Get("length"))
                {
                    parts.Push(south.Get("fromLagna").Call(lag.Join(Js.S(", "))));
                }
                if (moon.Get("length"))
                {
                    parts.Push(south.Get("fromMoon").Call(moon.Join(Js.S(", "))));
                }
                Js out_ = south.Get("mangal").Call(type, parts.Join(Js.S("; ")));
                if (d.Get("Cancelled"))
                {
                    out_ = Js.Add(out_, Js.Add(south.Get("cancelled"), MatchMaking.joinStrings(d.Get("CancelReasons"), Js.S(", "))));
                }
                return out_;
            }
            if ((!d.Get("Computed")))
            {
                if (Js.StrictEquals(l, Js.S("hi")))
                {
                    return Js.S("मंगल दोष की जाँच नहीं हुई — जन्म स्थान (अक्षांश/देशांतर) नहीं दिया गया।");
                }
                if (Js.StrictEquals(l, Js.S("mr")))
                {
                    return Js.S("मंगळ दोष तपासला नाही — जन्मस्थान (अक्षांश/रेखांश) दिलेले नाही.");
                }
                return Js.S("Mangal Dosha not evaluated — birth latitude/longitude not provided.");
            }
            if ((!d.Get("HasDosha")))
            {
                if (Js.StrictEquals(l, Js.S("hi")))
                {
                    return Js.S("मंगल दोष नहीं है।");
                }
                if (Js.StrictEquals(l, Js.S("mr")))
                {
                    return Js.S("मंगळ दोष नाही.");
                }
                return Js.S("No Mangal Dosha present.");
            }
            Js typeLabel = ((Js.StrictEquals(l, Js.S("hi")) || Js.StrictEquals(l, Js.S("mr"))) ? (Js.StrictEquals(d.Get("Type"), Js.S("purn")) ? Js.S("पूर्ण") : (Js.StrictEquals(d.Get("Type"), Js.S("mild")) ? Js.S("अल्प") : (d.Get("Type").NonNullish ?? Js.S("")))) : (Js.StrictEquals(d.Get("Type"), Js.S("purn")) ? Js.S("full") : (Js.StrictEquals(d.Get("Type"), Js.S("mild")) ? Js.S("mild") : (d.Get("Type").NonNullish ?? Js.S("")))));
            Js hs2 = Shared.listOf(d.Get("HousesOccupied"));
            Js lagnaH = hs2.Filter(Js.Fn(args1_ =>
            {
                Js h4 = Js.Arg(args1_, 0);
                return Js.Greater(h4, Js.N(0d));
            })).Map(Js.StringFunction);
            Js moonH = hs2.Filter(Js.Fn(args1_ =>
            {
                Js h5 = Js.Arg(args1_, 0);
                return Js.Less(h5, Js.N(0d));
            })).Map(Js.Fn(args1_ =>
            {
                Js h6 = Js.Arg(args1_, 0);
                return Js.ToStringValue(Js.Negate(h6));
            }));
            Js houseParts = Js.Arr();
            if (Js.StrictEquals(l, Js.S("hi")))
            {
                if (lagnaH.Get("length"))
                {
                    houseParts.Push(Js.Cat("लग्न से ", lagnaH.Join(Js.S(", ")).Str()));
                }
                if (moonH.Get("length"))
                {
                    houseParts.Push(Js.Cat("चंद्र से ", moonH.Join(Js.S(", ")).Str()));
                }
            }
            else if (Js.StrictEquals(l, Js.S("mr")))
            {
                if (lagnaH.Get("length"))
                {
                    houseParts.Push(Js.Cat("लग्नापासून ", lagnaH.Join(Js.S(", ")).Str()));
                }
                if (moonH.Get("length"))
                {
                    houseParts.Push(Js.Cat("चंद्रापासून ", moonH.Join(Js.S(", ")).Str()));
                }
            }
            else
            {
                if (lagnaH.Get("length"))
                {
                    houseParts.Push(Js.Cat(lagnaH.Join(Js.S(", ")).Str(), " from lagna"));
                }
                if (moonH.Get("length"))
                {
                    houseParts.Push(Js.Cat(moonH.Join(Js.S(", ")).Str(), " from Moon"));
                }
            }
            Js houses = houseParts.Join(Js.S("; "));
            Js out_2 = Js.Undefined;
            if (Js.StrictEquals(l, Js.S("hi")))
            {
                out_2 = Js.Cat("मंगल दोष (", typeLabel.Str(), ") — भाव: ", houses.Str(), "।");
            }
            else if (Js.StrictEquals(l, Js.S("mr")))
            {
                out_2 = Js.Cat("मंगळ दोष (", typeLabel.Str(), ") — स्थाने: ", houses.Str(), ".");
            }
            else
            {
                out_2 = Js.Cat("Mangal Dosha (", typeLabel.Str(), ") — house(s): ", houses.Str(), ".");
            }
            if (d.Get("Cancelled"))
            {
                Js reasons = MatchMaking.joinStrings(d.Get("CancelReasons"), Js.S(", "));
                if (Js.StrictEquals(l, Js.S("hi")))
                {
                    out_2 = Js.Add(out_2, Js.Add(Js.S(" रद्द: "), reasons));
                }
                else if (Js.StrictEquals(l, Js.S("mr")))
                {
                    out_2 = Js.Add(out_2, Js.Add(Js.S(" रद्द: "), reasons));
                }
                else
                {
                    out_2 = Js.Add(out_2, Js.Add(Js.S(" Cancelled: "), reasons));
                }
            }
            return out_2;
        }

        internal static Js nadiClass(Js n)
        {
            switch (n.Get("Severity").CaseKey())
            {
                case "exempted":
                return Js.S("cancelled");
                case "high":
                return Js.S("has-dosha");
                default:
                return Js.S("no-dosha");
            }
            return Js.Undefined;
        }

        internal static Js nadiSummary(Js loc, Js n)
        {
            Js l = MatchMaking.pickLocale(loc);
            Js boy = (n.Get("BoyNadi").NonNullish ?? Js.S(""));
            Js girl = (n.Get("GirlNadi").NonNullish ?? Js.S(""));
            Js south = MatchMaking.SOUTH_MATCH.Get(l);
            if (south)
            {
                if (Js.StrictEquals(n.Get("Severity"), Js.S("none")))
                {
                    return south.Get("nadiNone").Call(boy, girl);
                }
                if (Js.StrictEquals(n.Get("Severity"), Js.S("exempted")))
                {
                    return south.Get("nadiExempted").Call(MatchMaking.joinStrings(n.Get("Exceptions"), Js.S(", ")));
                }
                return south.Get("nadiHigh").Call(boy);
            }
            switch (n.Get("Severity").CaseKey())
            {
                case "none":
                if (Js.StrictEquals(l, Js.S("hi")))
                {
                    return Js.Cat("नाड़ी दोष नहीं है। (वर: ", boy.Str(), ", वधू: ", girl.Str(), ")");
                }
                if (Js.StrictEquals(l, Js.S("mr")))
                {
                    return Js.Cat("नाडी दोष नाही. (वर: ", boy.Str(), ", वधू: ", girl.Str(), ")");
                }
                return Js.Cat("No Nadi Dosha. (Boy: ", boy.Str(), ", Girl: ", girl.Str(), ")");
                case "exempted":
                {
                    Js exc = MatchMaking.joinStrings(n.Get("Exceptions"), Js.S(", "));
                    if (Js.StrictEquals(l, Js.S("hi")))
                    {
                        return Js.Cat("नाड़ी दोष है परन्तु शास्त्रीय अपवाद से रद्द (", exc.Str(), ")");
                    }
                    if (Js.StrictEquals(l, Js.S("mr")))
                    {
                        return Js.Cat("नाडी दोष आहे परंतु शास्त्रीय अपवादाने रद्द (", exc.Str(), ")");
                    }
                    return Js.Cat("Nadi Dosha present but exempted by classical rule (", exc.Str(), ")");
                }
                default:
                if (Js.StrictEquals(l, Js.S("hi")))
                {
                    return Js.Cat("नाड़ी दोष — दोनों की नाड़ी समान (", boy.Str(), ")। शास्त्रीय रूप से प्रतिकूल।");
                }
                if (Js.StrictEquals(l, Js.S("mr")))
                {
                    return Js.Cat("नाडी दोष — दोघांची नाडी समान (", boy.Str(), "). शास्त्रानुसार प्रतिकूल.");
                }
                return Js.Cat("Nadi Dosha — both share ", boy.Str(), " nadi. Classically unfavorable.");
            }
            return Js.Undefined;
        }

        internal static Js matchVerdict(Js data)
        {
            if (data.Get("FinalVerdict"))
            {
                return data.Get("FinalVerdict");
            }
            Js total = (data.Get("Ashtakoota").GetOptional("Total").NonNullish ?? Js.N(0d));
            if (Js.GreaterOrEqual(total, Js.N(24d)))
            {
                return Js.S("Marriage indications are favorable. Study both charts for the timing.");
            }
            return Js.S("Score is below conventional threshold (24/36). Consider remedies and a detailed study of both charts.");
        }

        internal static Js formatGenerated(Js iso)
        {
            if ((!iso))
            {
                return Js.S("");
            }
            Js d = Shared.parseTimestamp(iso);
            if (Js.IsNaN(d.GetTime()))
            {
                return iso;
            }
            Js p = Js.Fn(args1_ =>
            {
                Js n = Js.Arg(args1_, 0);
                return Js.ToStringValue(n).PadStart(Js.N(2d), Js.S("0"));
            });
            return Js.Cat(d.GetUtcFullYear().Str(), "-", p.Call(Js.Add(d.GetUtcMonth(), Js.N(1d))).Str(), "-", p.Call(d.GetUtcDate()).Str(), " ", p.Call(d.GetUtcHours()).Str(), ":", p.Call(d.GetUtcMinutes()).Str(), " UTC");
        }

        internal static readonly Js EXTRA_CSS = Js.S("\n.cover .subjects { display: flex; justify-content: space-around; align-items: flex-start; margin-top: 8mm; }\n.cover .subject-col { flex: 1; max-width: 40%; }\n.cover .subject-col h2 { color: var(--brand-primary); border: none; font-size: 18pt; margin-bottom: 4mm; padding: 0; }\n.cover .subject-col .meta { color: var(--brand-secondary); font-size: 10pt; }\n.cover .vs { align-self: center; font-size: 24pt; color: var(--brand-secondary); padding: 0 8mm; }\nth.score { text-align: right; }\ntd.score { text-align: right; font-weight: 600; font-variant-numeric: tabular-nums; }\ntr.total td { background: #fafafa; font-weight: 700; border-top: 2px solid var(--brand-primary); border-bottom: none; }\n.verdict { margin-top: 6mm; padding: 5mm; border: 1px solid var(--brand-primary); border-radius: 3mm; background: #fafafa; }\n.verdict.excellent { border-color: #166534; }\n.verdict.good { border-color: #65a30d; }\n.verdict.fair { border-color: #ca8a04; }\n.verdict.poor { border-color: #dc2626; }\n.verdict h3 { margin: 0 0 2mm; font-size: 14pt; }\n.dosha-block { margin-top: 4mm; padding: 4mm; background: #fafafa; border-left: 3px solid var(--brand-secondary); }\n.dosha-block.has-dosha { border-left-color: #dc2626; }\n.dosha-block.cancelled { border-left-color: #ca8a04; }\n.dosha-block.no-dosha { border-left-color: #166534; }\n");

        internal static Js renderMatchMakingHtml(Js data, Js branding)
        {
            data = Shared.withoutNullItems(Js.Obj(
                Js.Spread(data),
                Js.Prop("Locale", Shared.safeLocale(data.Get("Locale")))), Js.Undefined);
            Js resolved = Shared.resolveBranding(data.Get("Branding"), branding);
            Js t = Shared.makeLabeler(MatchMaking.LABELS, data.Get("Locale"));
            Js boy = (data.Get("Boy").NonNullish ?? Js.Obj());
            Js girl = (data.Get("Girl").NonNullish ?? Js.Obj());
            Js ashtakoota = (data.Get("Ashtakoota").NonNullish ?? Js.Obj());
            Js kootas = (Js.IsArray(ashtakoota.Get("Kootas")) ? ashtakoota.Get("Kootas") : Js.Arr());
            Js verdict = (ashtakoota.Get("Verdict").NonNullish ?? Js.S(""));
            Js boyName = (boy.Get("name").NonNullish ?? Js.S(""));
            Js girlName = (girl.Get("name").NonNullish ?? Js.S(""));
            Js subjectMeta = Js.Fn(args1_ =>
            {
                Js s = Js.Arg(args1_, 0);
                return Js.Cat(Shared.esc(t.Call(Js.S("born"))).Str(), " ", Shared.esc(s.Get("birth_date")).Str(), "<br>", Shared.esc(s.Get("birth_time")).Str(), "<br>", Shared.esc(s.Get("birth_place")).Str(), "<br>", Shared.esc(t.Call(Js.S("nakshatra"))).Str(), ": ", Shared.esc(s.Get("nakshatra")).Str());
            });
            Js cover = Js.Cat("<section class=\"cover\">\n  ", Shared.coverBrandingHtml(resolved).Str(), "\n  <h1>", Shared.esc(t.Call(Js.S("title_match"))).Str(), "</h1>\n  <div class=\"subjects\">\n    <div class=\"subject-col\">\n      <h2>", Shared.esc(boyName).Str(), "</h2>\n      <div class=\"meta\">", subjectMeta.Call(boy).Str(), "</div>\n    </div>\n    <div class=\"vs\">⚭</div>\n    <div class=\"subject-col\">\n      <h2>", Shared.esc(girlName).Str(), "</h2>\n      <div class=\"meta\">", subjectMeta.Call(girl).Str(), "</div>\n    </div>\n  </div>\n  <div class=\"generated\">", Shared.esc(t.Call(Js.S("generated"))).Str(), " ", Shared.esc(MatchMaking.formatGenerated(data.Get("GeneratedAt"))).Str(), "</div>\n</section>");
            Js kootaRows = kootas.Map(Js.Fn(args1_ =>
            {
                Js k = Js.Arg(args1_, 0);
                return Js.Cat("<tr><td>", Shared.esc(k.Get("name")).Str(), "</td><td class=\"score\">", Shared.esc(k.Get("Max")).Str(), "</td><td class=\"score\">", Shared.esc(k.Get("score")).Str(), "</td><td>", Shared.esc(k.Get("Reason")).Str(), "</td></tr>");
            })).Join(Js.S(""));
            Js totalRow = Js.Cat("<tr class=\"total\"><td>", Shared.esc(t.Call(Js.S("total"))).Str(), "</td><td class=\"score\">", Shared.esc(ashtakoota.Get("Max")).Str(), "</td><td class=\"score\">", Shared.esc(ashtakoota.Get("Total")).Str(), "</td><td>", Shared.esc(MatchMaking.verdictLabel(data.Get("Locale"), verdict)).Str(), "</td></tr>");
            Js ashtakootaTable = Js.Cat("<h2>", Shared.esc(t.Call(Js.S("section_ashtakoota"))).Str(), "</h2>\n<table>\n  <thead>\n    <tr>\n      <th>", Shared.esc(t.Call(Js.S("koota"))).Str(), "</th>\n      <th class=\"score\">", Shared.esc(t.Call(Js.S("max"))).Str(), "</th>\n      <th class=\"score\">", Shared.esc(t.Call(Js.S("score"))).Str(), "</th>\n      <th>", Shared.esc(t.Call(Js.S("details"))).Str(), "</th>\n    </tr>\n  </thead>\n  <tbody>", kootaRows.Str(), totalRow.Str(), "</tbody>\n</table>\n<div class=\"verdict ", Shared.esc(verdict).Str(), "\">\n  <h3>", Shared.esc(t.Call(Js.S("ashtakoota_verdict"))).Str(), ": ", Shared.esc(MatchMaking.verdictLabel(data.Get("Locale"), verdict)).Str(), "</h3>\n  <p>", Shared.esc(MatchMaking.verdictDescription(data.Get("Locale"), verdict)).Str(), "</p>\n</div>");
            Js mangalBoy = (data.Get("MangalDoshaBoy").NonNullish ?? Js.Obj());
            Js mangalGirl = (data.Get("MangalDoshaGirl").NonNullish ?? Js.Obj());
            Js nadi = (data.Get("NadiDosha").NonNullish ?? Js.Obj());
            Js doshas = Js.Cat("<h2>", Shared.esc(t.Call(Js.S("section_doshas"))).Str(), "</h2>\n<h3>", Shared.esc(t.Call(Js.S("mangal_dosha"))).Str(), " — ", Shared.esc(boyName).Str(), "</h3>\n<div class=\"dosha-block ", Shared.esc(MatchMaking.doshaClass(mangalBoy)).Str(), "\">", Shared.esc(MatchMaking.doshaSummary(data.Get("Locale"), mangalBoy)).Str(), "</div>\n<h3>", Shared.esc(t.Call(Js.S("mangal_dosha"))).Str(), " — ", Shared.esc(girlName).Str(), "</h3>\n<div class=\"dosha-block ", Shared.esc(MatchMaking.doshaClass(mangalGirl)).Str(), "\">", Shared.esc(MatchMaking.doshaSummary(data.Get("Locale"), mangalGirl)).Str(), "</div>\n<h3>", Shared.esc(t.Call(Js.S("nadi_dosha"))).Str(), "</h3>\n<div class=\"dosha-block ", Shared.esc(MatchMaking.nadiClass(nadi)).Str(), "\">", Shared.esc(MatchMaking.nadiSummary(data.Get("Locale"), nadi)).Str(), "</div>");
            Js finalVerdict = Js.Cat("<h2>", Shared.esc(t.Call(Js.S("section_final"))).Str(), "</h2>\n<div class=\"verdict ", Shared.esc(verdict).Str(), "\">\n  <p>", Shared.esc(MatchMaking.matchVerdict(data)).Str(), "</p>\n</div>");
            Js bodyHtml = Js.Arr(cover, ashtakootaTable, doshas, finalVerdict).Join(Js.S("\n\n"));
            return Shared.layoutDocument(Js.Obj(
                Js.Prop("lang", data.Get("Locale")),
                Js.Prop("title", Js.Cat(t.Call(Js.S("title_match")).Str(), " — ", boyName.Str(), " × ", girlName.Str())),
                Js.Prop("branding", resolved),
                Js.Prop("bodyHtml", bodyHtml),
                Js.Prop("extraCss", MatchMaking.EXTRA_CSS)));
        }
    }
}
